#!/usr/bin/env python3
# Generates src/gen_info.rs and src/gen_tables.rs from linuxdoom-1.10's
# info.h/info.c/sounds.h/sounds.c/tables.c/m_random.c.
# Usage: python3 gen/gen.py /path/to/linuxdoom-1.10
# The generated files are committed; this script is only needed to regenerate them.
import re, sys, os

src = sys.argv[1] if len(sys.argv) > 1 else '/app/data/home/doom-ref/DOOM/linuxdoom-1.10'
out = os.path.join(os.path.dirname(__file__), '..', 'src')

def rd(n):
    return open(os.path.join(src, n), encoding='latin1').read()

def strip_comments(s):
    s = re.sub(r'/\*.*?\*/', '', s, flags=re.S)
    s = re.sub(r'//[^\n]*', '', s)
    return s

HEADER = """// Generated by sim/gen/gen.py from id Software's linuxdoom-1.10 sources.
// Copyright (C) 1993-1996 by id Software, Inc.
// This program is free software; you can redistribute it and/or modify it under the
// terms of the GNU General Public License version 2 (GPL-2.0) as published by the Free
// Software Foundation.
// DO NOT EDIT BY HAND.
#![allow(clippy::all, non_upper_case_globals, dead_code)]
"""

info_h = strip_comments(rd('info.h'))
info_c = strip_comments(rd('info.c'))
sounds_h = strip_comments(rd('sounds.h'))
sounds_c = strip_comments(rd('sounds.c'))
tables_c = strip_comments(rd('tables.c'))
random_c = strip_comments(rd('m_random.c'))
mobj_h = strip_comments(rd('p_mobj.h'))

def enum_names(text, first, last):
    i = text.index(first)
    j = text.index(last, i)
    body = text[i:j]
    return [x.strip() for x in body.split(',') if x.strip()]

sprites = enum_names(info_h, 'SPR_TROO', 'NUMSPRITES')
statesn = enum_names(info_h, 'S_NULL', 'NUMSTATES')
mts = enum_names(info_h, 'MT_PLAYER', 'NUMMOBJTYPES')
sfxs = enum_names(sounds_h, 'sfx_None', 'NUMSFX')

sym = {}
for i, n in enumerate(sprites): sym[n] = i
for i, n in enumerate(statesn): sym[n] = i
for i, n in enumerate(mts): sym[n] = i
for i, n in enumerate(sfxs): sym[n] = i
for m in re.finditer(r'(MF_\w+)\s*=\s*(0x[0-9a-fA-F]+|\d+)', mobj_h):
    sym[m.group(1)] = int(m.group(2), 0)
sym['FRACUNIT'] = 65536
sym['NULL'] = 0

def ev(expr):
    expr = expr.strip()
    def rep(m):
        w = m.group(0)
        if w in sym: return str(sym[w])
        raise Exception('unknown symbol ' + w)
    e = re.sub(r'[A-Za-z_]\w*', rep, expr)
    return int(eval(e))

# sprnames
m = re.search(r'char \*sprnames\[NUMSPRITES\]\s*=\s*\{(.*?)\};', info_c, re.S)
sprnames = re.findall(r'"(\w+)"', m.group(1))
assert len(sprnames) == len(sprites), (len(sprnames), len(sprites))

# states
m = re.search(r'state_t\s+states\[NUMSTATES\]\s*=\s*\{(.*)\};\s*mobjinfo_t', info_c, re.S)
rows = re.findall(r'\{(SPR_\w+),([^,]+),([^,]+),\{(\w+)\},(\w+),([^,]+),([^}]+)\}', m.group(1))
assert len(rows) == len(statesn), (len(rows), len(statesn))
actions = ['None']
states = []
for r in rows:
    act = r[3]
    if act == 'NULL':
        a = 'None'
    else:
        a = act[2:]
        if a not in actions: actions.append(a)
    states.append((sym[r[0]], ev(r[1]), ev(r[2]), a, sym[r[4]], ev(r[5]), ev(r[6])))

# mobjinfo
m = re.search(r'mobjinfo_t mobjinfo\[NUMMOBJTYPES\]\s*=\s*\{(.*)\};', info_c, re.S)
blocks = re.findall(r'\{([^{}]*)\}', m.group(1))
assert len(blocks) == len(mts), (len(blocks), len(mts))
fields = ['doomednum','spawnstate','spawnhealth','seestate','seesound','reactiontime','attacksound','painstate','painchance','painsound','meleestate','missilestate','deathstate','xdeathstate','deathsound','speed','radius','height','mass','damage','activesound','flags','raisestate']
infos = []
for b in blocks:
    vals = [x.strip() for x in b.split(',') if x.strip()]
    assert len(vals) == 23, vals
    infos.append([ev(v) for v in vals])

# Additions beyond vanilla, appended after its tables so every vanilla index stays put
# (DESIGN.md "Battle royale" and "Battle royale v2"). Crates, the dropship, parachuters
# and buggies borrow existing sprites (BAR1A / PLAYA-B) as fallbacks: the client draws
# them as 3D models. SNPR/SNPG/SNPF/GREN are new sprite names whose patches the client
# generates.
EXTRA_SPRITES = ['SNPR', 'SNPG', 'SNPF', 'GREN']
for n in EXTRA_SPRITES:
    sym['SPR_' + n] = len(sprites)
    sprites.append('SPR_' + n)
    sprnames.append(n)
EXTRA_STATES = [
    ('S_CRATE', ('SPR_BAR1', '0', '-1', 'None', 'S_CRATE', '0', '0')),             # 967
    ('S_DROPSHIP', ('SPR_BAR1', '0', '-1', 'None', 'S_DROPSHIP', '0', '0')),       # 968
    ('S_PARA_FALL', ('SPR_PLAY', '0', '-1', 'None', 'S_PARA_FALL', '0', '0')),     # 969 frame A freefall
    ('S_PARA_OPEN', ('SPR_PLAY', '1', '-1', 'None', 'S_PARA_OPEN', '0', '0')),     # 970 frame B chute open
    ('S_BUGGY', ('SPR_BAR1', '0', '-1', 'None', 'S_BUGGY', '0', '0')),             # 971
    ('S_SNIPERRIFLE', ('SPR_SNPR', '0', '-1', 'None', 'S_SNIPERRIFLE', '0', '0')), # 972 pickup
    ('S_GRENADE', ('SPR_GREN', '0', '-1', 'None', 'S_GRENADE', '0', '0')),         # 973 in flight
    ('S_GRENADEPACK', ('SPR_GREN', '0', '-1', 'None', 'S_GRENADEPACK', '0', '0')), # 974 pickup
    ('S_SNIPER', ('SPR_SNPG', '0', '1', 'WeaponReady', 'S_SNIPER', '0', '0')),     # 975
    ('S_SNIPERDOWN', ('SPR_SNPG', '0', '1', 'Lower', 'S_SNIPERDOWN', '0', '0')),   # 976
    ('S_SNIPERUP', ('SPR_SNPG', '0', '1', 'Raise', 'S_SNIPERUP', '0', '0')),       # 977
    ('S_SNIPER1', ('SPR_SNPG', '1', '4', 'FireSniper', 'S_SNIPER2', '0', '0')),    # 978 fire
    ('S_SNIPER2', ('SPR_SNPG', '2', '23', 'None', 'S_SNIPER3', '0', '0')),         # 979 bolt
    ('S_SNIPER3', ('SPR_SNPG', '3', '23', 'None', 'S_SNIPER4', '0', '0')),         # 980 bolt
    ('S_SNIPER4', ('SPR_SNPG', '0', '5', 'ReFire', 'S_SNIPER', '0', '0')),         # 981 (held: a shot every 4+23+23 = 50 tics)
    ('S_SNIPERFLASH', ('SPR_SNPF', '32768', '4', 'Light1', 'S_LIGHTDONE', '0', '0')), # 982
]
def mobj(doomednum, state, health, radius, height, mass, flags):
    return [doomednum, state, health, 'S_NULL', 'sfx_None', '8', 'sfx_None', 'S_NULL', '0', 'sfx_None',
            'S_NULL', 'S_NULL', 'S_NULL', 'S_NULL', 'sfx_None', '0', radius, height, mass,
            '0', 'sfx_None', flags, 'S_NULL']
EXTRA_MOBJS = [
    ('MT_CRATE', mobj('9020', 'S_CRATE', '25', '20*FRACUNIT', '40*FRACUNIT', '100', 'MF_SOLID|MF_SHOOTABLE|MF_NOBLOOD')),      # 137
    ('MT_DROPSHIP', mobj('-1', 'S_DROPSHIP', '1000', '64*FRACUNIT', '64*FRACUNIT', '100', 'MF_NOBLOCKMAP|MF_NOGRAVITY|MF_NOCLIP')),  # 138
    ('MT_PARACHUTER', mobj('-1', 'S_PARA_FALL', '1000', '16*FRACUNIT', '56*FRACUNIT', '100', 'MF_NOBLOCKMAP|MF_NOGRAVITY|MF_NOCLIP')),  # 139
    ('MT_BUGGY', mobj('9040', 'S_BUGGY', '400', '32*FRACUNIT', '48*FRACUNIT', '1000', 'MF_SOLID|MF_SHOOTABLE|MF_NOBLOOD')),   # 140
    ('MT_SNIPERRIFLE', mobj('9050', 'S_SNIPERRIFLE', '1000', '20*FRACUNIT', '16*FRACUNIT', '100', 'MF_SPECIAL')),            # 141
    ('MT_GRENADE', mobj('-1', 'S_GRENADE', '1000', '4*FRACUNIT', '8*FRACUNIT', '100', 'MF_NOBLOCKMAP|MF_DROPOFF')),          # 142
    ('MT_GRENADEPACK', mobj('9051', 'S_GRENADEPACK', '1000', '20*FRACUNIT', '16*FRACUNIT', '100', 'MF_SPECIAL')),            # 143
]
for n, _ in EXTRA_STATES:
    sym[n] = len(statesn)
    statesn.append(n)
for n, r in EXTRA_STATES:
    if r[3] != 'None' and r[3] not in actions:
        actions.append(r[3])
    states.append((sym[r[0]], ev(r[1]), ev(r[2]), r[3], sym[r[4]], ev(r[5]), ev(r[6])))
for n, vals in EXTRA_MOBJS:
    sym[n] = len(mts)
    mts.append(n)
    infos.append([ev(v) for v in vals])

# sounds
m = re.search(r'sfxinfo_t S_sfx\[\]\s*=\s*\{(.*?)\};', sounds_c, re.S)
sfx = re.findall(r"\{\s*\"(\w+)\"\s*,\s*(\w+)\s*,\s*(-?\d+)\s*,", m.group(1))
assert len(sfx) == len(sfxs), (len(sfx), len(sfxs))

o = [HEADER]
o.append('use crate::info::{State, MobjInfo, Action};\n')
o.append('pub const NUMSPRITES: usize = %d;\n' % len(sprites))
o.append('pub const NUMSTATES: usize = %d;\n' % len(statesn))
o.append('pub const NUMMOBJTYPES: usize = %d;\n' % len(mts))
o.append('pub const NUMSFX: usize = %d;\n' % len(sfxs))
o.append('pub const SPRNAMES: [&str; NUMSPRITES] = [%s];\n' % ','.join('"%s"' % s for s in sprnames))
# "none" is the dummy at 0: export "" per DESIGN
o.append('pub const SFXNAMES: [&str; NUMSFX] = [%s];\n' % ','.join('"%s"' % ('' if i == 0 else s[0]) for i, s in enumerate(sfx)))
o.append('pub const SFXPRIORITY: [i32; NUMSFX] = [%s];\n' % ','.join(s[2] for s in sfx))
o.append('#[allow(non_camel_case_types)]\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\n#[repr(u8)]\npub enum ActionGen { %s }\n' % ', '.join(actions))
o.append('pub static STATES: [State; NUMSTATES] = [\n')
for s in states:
    o.append('State{sprite:%d,frame:%d,tics:%d,action:Action::%s,next:%d,misc1:%d,misc2:%d},\n' % s)
o.append('];\n')
o.append('pub static MOBJINFO: [MobjInfo; NUMMOBJTYPES] = [\n')
for inf in infos:
    o.append('MobjInfo{' + ','.join('%s:%d' % (f, v) for f, v in zip(fields, inf)) + '},\n')
o.append('];\n')
# symbolic constants
o.append('#[allow(dead_code)]\npub mod spr {\n' + ''.join('pub const %s: usize = %d;\n' % (n[4:], i) for i, n in enumerate(sprites)) + '}\n')
o.append('#[allow(dead_code)]\npub mod st {\n' + ''.join('pub const %s: usize = %d;\n' % (n[2:], i) for i, n in enumerate(statesn)) + '}\n')
o.append('#[allow(dead_code)]\npub mod mt {\n' + ''.join('pub const %s: usize = %d;\n' % (n[3:], i) for i, n in enumerate(mts)) + '}\n')
o.append('#[allow(dead_code)]\npub mod sfx {\n' + ''.join('pub const %s: i32 = %d;\n' % (n[4:], i) for i, n in enumerate(sfxs)) + '}\n')
gi = ''.join(o)
gi = gi.replace('Action::', 'ActionGen::').replace('use crate::info::{State, MobjInfo, Action};', 'use crate::info::{State, MobjInfo};')
gi = gi.replace('action:ActionGen', 'action:ActionGen')
open(os.path.join(out, 'gen_info.rs'), 'w').write(gi)

def arr(name, ty, text, cname):
    m = re.search(cname + r'\[\d+\]\s*=\s*\{(.*?)\};', text, re.S)
    vals = [v.strip() for v in m.group(1).split(',') if v.strip()]
    return 'pub static %s: [%s; %d] = [%s];\n' % (name, ty, len(vals), ','.join(vals))

t = [HEADER]
t.append(arr('FINETANGENT', 'i32', tables_c, 'int finetangent'))
t.append(arr('FINESINE', 'i32', tables_c, 'int finesine'))
t.append(arr('TANTOANGLE', 'u32', tables_c, 'angle_t tantoangle'))
t.append(arr('RNDTABLE', 'u8', random_c, 'unsigned char rndtable'))
open(os.path.join(out, 'gen_tables.rs'), 'w').write(''.join(t))
print('sprites', len(sprites), 'states', len(statesn), 'mobjtypes', len(mts), 'sfx', len(sfxs), 'actions', len(actions))
